function mergeCards(cards) {
  const parent = new Map()
  const find = x => {
    while (parent.get(x) !== x) {
      parent.set(x, parent.get(parent.get(x)))
      x = parent.get(x)
    }
    return x
  }
  for (const card of cards) {
    for (const id of card) if (!parent.has(id)) parent.set(id, id)
    const root = find(card[0])
    for (const id of card) {
      const other = find(id)
      if (other !== root) parent.set(other, root)
    }
  }
  const groups = new Map()
  for (const id of parent.keys()) {
    const root = find(id)
    if (!groups.has(root)) groups.set(root, [])
    groups.get(root).push(id)
  }
  const people = [...groups.values()].map(ids => ids.sort())
  return people.sort((a, b) => (a[0] < b[0] ? -1 : 1))
}

