def merge_cards(cards):
    parent = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for card in cards:
        for ident in card:
            parent.setdefault(ident, ident)
        root = find(card[0])
        for ident in card:
            other = find(ident)
            if other != root:
                parent[other] = root

    groups = {}
    for ident in parent:
        groups.setdefault(find(ident), []).append(ident)
    return sorted((sorted(ids) for ids in groups.values()), key=lambda ids: ids[0])
